import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第十三卦 同人 天火同人 乾上离下","description":"周易 - 第十三卦 同人 天火同人 乾上离下","frontmatter":{"title":"第十三卦 同人 天火同人 乾上离下","description":"周易 - 第十三卦 同人 天火同人 乾上离下"},"headers":[],"relativePath":"zh/classics/zhouyi/014.md","filePath":"zh/classics/zhouyi/014.md"}'),l={name:"zh/classics/zhouyi/014.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="同人" tabindex="-1">同人 <a class="header-anchor" href="#同人" aria-label="Permalink to “同人”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>同人于野，亨。利涉大川，利君子贞。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>同人，柔得位得中，而应乎乾，曰同人。同人曰，同人于野，亨。利涉大川，乾行也。文明以健，中正而应，君子正也。唯君子为能通天下之志。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>天与火，同人；君子以类族辨物。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>同人于门，无咎。象曰：出门同人，又 谁咎也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>同人于宗，吝。象曰：同人于宗，吝道也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>伏戎于莽，升其高陵，三岁不兴。象曰：伏戎于莽，敌刚也。三岁不兴，安行也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>乘其墉，弗克攻，吉。象曰：乘其墉，义弗克也，其吉，则困而反则也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>同人，先号啕而后笑。大师克相遇。象曰：同人之先，以中直也。大师相遇，言相克也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>同人于郊，无悔。象曰：同人于郊，志未得也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
